import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

fn make() -> conc.Mutex<Int64> {
    return conc.Mutex(41)
}

fn churn() -> Int64 {
    let total = 0i64
    for i in 0..200000 {
        let m = make()
        let _ = m.set(i)
        total = total + m.get() - i
    }
    return total + 41
}

pub fn main() effect io -> Result<(), AppError> {
    io.println("churn ${churn()}")
    return Ok(())
}
